<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('Administrator','Management','Event');$pageTitle='Management Calendar';$s=db()->query('SELECT * FROM vw_calendar_events ORDER BY start_at DESC LIMIT 100');$events=$s->fetchAll();require __DIR__.'/../../includes/header.php';?><div class="admin-shell"><aside class="sidebar"><?php require __DIR__.'/../sidebar.php';?></aside><section class="admin-content"><div class="admin-top"><div><div class="eyebrow">Operations</div><h1 class="admin-title">Management calendar</h1><p class="kicker">Full operational visibility across published and internal events.</p></div></div><div class="panel table-wrap"><table class="table"><thead><tr><th>Event</th><th>Category</th><th>Venue</th><th>Start</th><th>Status</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><b><?=e($e['title'])?></b></td><td><?=e($e['category_name']??'—')?></td><td><?=e($e['venue_names']??'TBA')?></td><td><?=date('d M Y · H:i',strtotime($e['start_at']))?></td><td><span class="badge <?=$e['status']==='confirmed'?'badge-green':($e['status']==='cancelled'?'badge-red':'badge-gold')?>"><?=e(ucwords($e['status']))?></span></td></tr><?php endforeach;?></tbody></table></div></section></div><?php require __DIR__.'/../../includes/footer.php';?>
